"""Курсы Scratch, Figma и Tilda (только уроки, проверяет учитель). Собирает studio_courses.py."""
from __future__ import annotations


def P(ru, kk):
    return {"p": [ru, kk]}


def H(ru, kk):
    return {"h": [ru, kk]}


def OL(*items):
    return {"ol": [list(i) for i in items]}


def TIP(ru, kk):
    return {"tip": [ru, kk]}


def TASK(ru, kk):
    return {"task": [ru, kk]}


STEPS = ("Шаг за шагом", "Қадам-қадаммен")


def L(n, title, goal, *theory):
    return {"number": n, "title": list(title), "goal": list(goal), "theory": list(theory), "tasks": []}


